import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/architecture.md","filePath":"zh/architecture.md"}`),a={name:`zh/architecture.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to “架构”">​</a></h1><p>FaultDeck 是一个 Rust workspace。当前实现包含 <strong>6 个已构建 crate</strong>,外加一个空占位(<code>faultdeck-protocol</code> —— 目录存在,但没有 <code>Cargo.toml</code>,<strong>尚未加入 workspace</strong>)。<a href="/faultdeck/zh/design/mvp-plan.html">MVP 计划</a>中的 toxiproxy 后端与场景 YAML DSL 尚未实现;如今的实现后端是 <code>tc netem</code> + <code>iptables</code>。</p><h2 id="crate-一览" tabindex="-1">Crate 一览 <a class="header-anchor" href="#crate-一览" aria-label="Permalink to “Crate 一览”">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>二进制</th><th>职责</th></tr></thead><tbody><tr><td><code>faultdeck-core</code></td><td>—</td><td>共享模型:<code>FaultSpec</code>(latency / loss / disconnect)、<code>Target</code>、<code>Injection</code>、内在校验(<code>validate_injection</code>)、管理网段重叠检查</td></tr><tr><td><code>faultdeck-netem</code></td><td>—</td><td><code>tc</code> 适配器:规划并执行 <code>tc qdisc</code>/<code>filter</code> 命令,preflight 检查,回滚,<code>dry_run</code> 执行器</td></tr><tr><td><code>faultdeck-agent</code></td><td><code>faultdeck-agent</code></td><td>常驻 TCP 守护进程:token 鉴权、请求处理、iptables 防火墙(disconnect)、单故障状态</td></tr><tr><td><code>faultdeck-coordinator</code></td><td><code>faultdeck-coordinator</code></td><td>多目标中枢:agent 注册表(register/heartbeat/list 含在线状态)、报告归档、经 agent 反向链路在线下发 inject/rollback,离线 agent 指令入队</td></tr><tr><td><code>faultdeck-report</code></td><td>—</td><td><code>Scenario</code>、<code>RunReport</code>(JSON/HTML)、SHA-256 场景哈希、<code>compare_runs</code> 历史 diff</td></tr><tr><td><code>faultdeck-cli</code></td><td><code>faultdeck</code></td><td>CLI 入口:<code>faultdeck remote ping / inject / rollback</code>(直连 agent)与 <code>faultdeck hub list / inject / rollback</code>(经 coordinator)</td></tr><tr><td><code>faultdeck-protocol</code></td><td>—</td><td><em>占位,不在 workspace 中</em></td></tr></tbody></table><h2 id="交互总览" tabindex="-1">交互总览 <a class="header-anchor" href="#交互总览" aria-label="Permalink to “交互总览”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> faultdeck CLI                faultdeck-agent                目标主机</span></span>
<span class="line"><span> ┌──────────────┐  TCP 换行   ┌──────────────────┐   tc      ┌──────────┐</span></span>
<span class="line"><span> │ remote ping  │  分帧 JSON  │ token 鉴权        │──qdisc──▶ │  eth0    │</span></span>
<span class="line"><span> │ remote inject│             │ 管理网段守卫       │──filter─▶ │ (netem)  │</span></span>
<span class="line"><span> │ remote       │             │ validate_injection│           └──────────┘</span></span>
<span class="line"><span> │   rollback   │             │                  │  iptables ┌──────────┐</span></span>
<span class="line"><span> └──────────────┘             │ firewall (mangle)│──DROP────▶│ disconnect│</span></span>
<span class="line"><span>                              └──────────────────┘  -t mangle└──────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span> faultdeck-coordinator(默认 :7001)</span></span>
<span class="line"><span> ┌────────────────────────────────────────────┐</span></span>
<span class="line"><span> │ 注册表: agents / reports / links / queues   │◀── 换行分帧 JSON(多消息长连接,</span></span>
<span class="line"><span> │ AgentCommand: register, heartbeat,         │    线程化 accept)</span></span>
<span class="line"><span> │   inject, rollback, fetch_report,          │◀── agent 反向链路:先 RegisterEnvelope,</span></span>
<span class="line"><span> │   list_agents                              │    再 LinkMessage::Dispatch → Result /</span></span>
<span class="line"><span> │                                            │    Heartbeat 同链路往返</span></span>
<span class="line"><span> └────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="线协议-cli-↔-agent" tabindex="-1">线协议(CLI ↔ agent) <a class="header-anchor" href="#线协议-cli-↔-agent" aria-label="Permalink to “线协议(CLI ↔ agent)”">​</a></h2><p>每次 CLI 调用一条 TCP 连接。客户端发一行,agent 应答一行 JSON 后关闭。</p><ul><li>带 token:<code>&lt;token&gt; {json}\\n</code> —— 不带:<code>{json}\\n</code></li><li>请求:<code>{&quot;cmd&quot;:&quot;ping&quot;}</code> | <code>{&quot;cmd&quot;:&quot;inject&quot;, …Injection}</code> | <code>{&quot;cmd&quot;:&quot;rollback&quot;}</code></li><li>响应:<code>{&quot;status&quot;:&quot;ok&quot;,&quot;message&quot;:&quot;…&quot;}</code> | <code>{&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;…&quot;}</code></li></ul><h2 id="线协议-coordinator" tabindex="-1">线协议(coordinator) <a class="header-anchor" href="#线协议-coordinator" aria-label="Permalink to “线协议(coordinator)”">​</a></h2><p>长连接,双向按行分帧的 JSON(<code>faultdeck-agent::transport</code>)。同一监听端口承载两种会话,按首帧区分:</p><ul><li><strong>控制端会话</strong> —— 每条命令一个 <code>WireMessage</code> 信封。<code>AgentCommand</code>:<code>register</code> | <code>heartbeat</code> | <code>inject</code> | <code>rollback</code> | <code>fetch_report</code> | <code>list_agents</code>;<code>AgentResponse</code>:<code>ok</code> | <code>error</code> | <code>registered</code> | <code>queued</code> | <code>agents</code> | <code>report</code>。</li><li><strong>Agent 链路</strong> —— agent 主动出站拨号 coordinator(可穿双向 NAT),首帧发 <code>RegisterEnvelope</code>(<code>crates/agent/src/link.rs:46</code>);此后 coordinator 沿同一条连接写 <code>LinkMessage::Dispatch</code>,agent 以 <code>LinkMessage::Result</code> 应答并周期发送 <code>LinkMessage::Heartbeat</code>。</li></ul><p>状态保存在 <code>Mutex&lt;CoordinatorState&gt;</code>:<code>agents</code>、<code>reports</code>、<code>links</code>(存活反向连接)、每 agent 的 <code>queues</code> 均为 <code>BTreeMap</code>。</p><p><strong>实现状态:</strong> coordinator 的 <code>inject</code>/<code>rollback</code> 先校验、归档报告桩,然后<strong>真实下发</strong> —— 存活链路立即收到指令,agent 的执行结果回传给等待中的控制端(受 <code>DEFAULT_DISPATCH_TIMEOUT</code> 5 s 约束)并合入归档报告;agent 离线时指令持久入队,在其下次注册时补发。<code>list_agents</code> 依据链路存活或心跳新鲜度(<code>HEARTBEAT_TIMEOUT_MS</code> 30 s)标注每项 <code>AgentIdentity.online</code>,离线 agent 从 <code>available</code> 中剔除。</p><h2 id="netem-适配器的失败处理" tabindex="-1">netem 适配器的失败处理 <a class="header-anchor" href="#netem-适配器的失败处理" aria-label="Permalink to “netem 适配器的失败处理”">​</a></h2><ol><li><code>plan()</code> 只校验并返回命令列表,不执行。</li><li><code>inject()</code> 先跑 preflight <code>tc qdisc show</code> —— 若网卡根 qdisc 不是 FaultDeck 的 <code>100:</code> 句柄,拒绝操作。</li><li>应用前先清理上一次运行遗留的 FaultDeck 根 qdisc。</li><li>应用过程中任何命令失败,适配器立即下发回滚命令。</li><li><code>rollback()</code> 删除根 qdisc;<code>tc</code> 的「找不到」类错误按已清理处理(幂等)。</li></ol><p>disconnect 故障完全绕过 <code>tc</code> —— 见 <a href="/faultdeck/zh/netem-faults.html#disconnect">Netem 故障</a>。</p><h2 id="源码分层解说" tabindex="-1">源码分层解说 <a class="header-anchor" href="#源码分层解说" aria-label="Permalink to “源码分层解说”">​</a></h2><p>源码职责层与 crate 目录名相互独立。术语已同步到<a href="/faultdeck/zh/glossary.html">术语表</a>。</p><h3 id="_1-共享语义与安全模型" tabindex="-1">1. 共享语义与安全模型 <a class="header-anchor" href="#_1-共享语义与安全模型" aria-label="Permalink to “1. 共享语义与安全模型”">​</a></h3><p><code>crates/core/src/lib.rs</code> 拥有 <code>FaultSpec</code>、<code>Target</code>、<code>Injection</code>、内在校验和管理网段重叠检查(<code>crates/core/src/lib.rs:26</code>、<code>crates/core/src/lib.rs:44</code>、<code>crates/core/src/lib.rs:82</code>、<code>crates/core/src/lib.rs:108</code>、<code>crates/core/src/lib.rs:142</code>)。该层无持久状态、无网络 I/O。schema 是 Rust Serde 模型和 <code>crates/core/src/lib.rs:88</code> 的内在校验错误;故障语义文案在 <a href="/faultdeck/zh/netem-faults.html">Netem 故障</a>,没有专属协议文件。</p><h3 id="_2-策略到后端翻译层" tabindex="-1">2. 策略到后端翻译层 <a class="header-anchor" href="#_2-策略到后端翻译层" aria-label="Permalink to “2. 策略到后端翻译层”">​</a></h3><p><code>crates/netem/src/lib.rs</code> 通过 <code>NetemAdapter</code> 把已校验的延迟/丢包翻译成有序 <code>tc qdisc</code> 和 <code>filter</code> 命令(<code>crates/netem/src/lib.rs:172</code>、<code>crates/netem/src/lib.rs:199</code>、<code>crates/netem/src/lib.rs:204</code>)。执行端口是 <code>CommandExecutor</code>(<code>crates/netem/src/lib.rs:73</code>),命令 schema 是 <code>TcCommand</code>(<code>crates/netem/src/lib.rs:56</code>),运行输入为网卡名和可选 dry-run 执行器设置(<code>crates/netem/src/lib.rs:172</code>、<code>crates/netem/src/lib.rs:80</code>)。调用之间无状态、无网络协议;实现细节见 <a href="/faultdeck/zh/architecture.html#netem-适配器的失败处理">架构</a>。</p><h3 id="_3-宿主执行与防护层" tabindex="-1">3. 宿主执行与防护层 <a class="header-anchor" href="#_3-宿主执行与防护层" aria-label="Permalink to “3. 宿主执行与防护层”">​</a></h3><p><code>crates/agent/src/lib.rs</code> 是 Agent 宿主:接收 TCP、鉴权、防护管理网段、解码请求、路由 disconnect 或 netem,并用 <code>Arc&lt;Mutex&lt;HashSet&lt;String&gt;&gt;&gt;</code> 保存活动故障标记(<code>crates/agent/src/lib.rs:171</code>、<code>crates/agent/src/lib.rs:326</code>、<code>crates/agent/src/lib.rs:340</code>)。配置 schema 是 <code>AgentConfig</code>(<code>crates/agent/src/lib.rs:90</code>),由 <code>crates/agent/src/main.rs:9</code> 填充;这些输入记录在<a href="/faultdeck/zh/configuration.html">配置</a>。<code>crates/agent/src/firewall.rs:31</code> 的 <code>Iptables</code> 执行主机规则;协议类型仍在 <code>crates/agent/src/lib.rs:109</code> 和 <code>crates/agent/src/lib.rs:117</code>,没有专属协议文件。</p><h3 id="_4-线传输与拓扑层" tabindex="-1">4. 线传输与拓扑层 <a class="header-anchor" href="#_4-线传输与拓扑层" aria-label="Permalink to “4. 线传输与拓扑层”">​</a></h3><p><code>crates/agent/src/transport.rs</code> 拥有带界限的 NDJSON 分帧、Mode A 监听/接受和 Mode B 反向连接(<code>crates/agent/src/transport.rs:56</code>、<code>crates/agent/src/transport.rs:94</code>、<code>crates/agent/src/transport.rs:118</code>)。除已接受 socket 外无状态。分帧 schema 是通用 <code>send_frame</code>/<code>read_frame</code>(<code>crates/agent/src/transport.rs:57</code>、<code>crates/agent/src/transport.rs:65</code>)。在此分帧之上,<code>crates/agent/src/link.rs</code> 实现可用的 Mode B 链路会话 —— 注册信封、心跳线程、分发泵,以及可重连的 <code>run_link</code> 循环(<code>crates/agent/src/link.rs:77</code>、<code>crates/agent/src/link.rs:140</code>、<code>crates/agent/src/link.rs:184</code>)。拓扑文案在 <a href="/faultdeck/zh/remote-agents.html">Agents</a>,载荷类型分属 agent 与 coordinator 层,<code>crates/protocol/src</code> 为空目录。</p><h3 id="_5-用户入口与报告物化层" tabindex="-1">5. 用户入口与报告物化层 <a class="header-anchor" href="#_5-用户入口与报告物化层" aria-label="Permalink to “5. 用户入口与报告物化层”">​</a></h3><p><code>crates/cli/src/main.rs</code> 把 <code>remote ping/inject/rollback</code> 与 <code>hub list/inject/rollback</code> 参数转换为共享 <code>Injection</code>,与 agent 或 coordinator 执行有超时的 TCP 交互,按需物化 JSON/HTML 报告并生成回放命令(<code>crates/cli/src/main.rs:136</code>、<code>crates/cli/src/main.rs:165</code>、<code>crates/cli/src/main.rs:227</code>、<code>crates/cli/src/main.rs:341</code>)。它没有服务端状态;文件输出由调用参数指定。命令 schema 是 <code>crates/cli/src/main.rs:22</code> 的 clap 树,唯一环境输入是 <code>FAULTDECK_TIMEOUT_SECS</code>(<code>crates/cli/src/main.rs:236</code>),用户旗标记录在<a href="/faultdeck/zh/configuration.html">配置</a>。</p><h3 id="_6-机群注册与控制面状态层" tabindex="-1">6. 机群注册与控制面状态层 <a class="header-anchor" href="#_6-机群注册与控制面状态层" aria-label="Permalink to “6. 机群注册与控制面状态层”">​</a></h3><p><code>crates/coordinator/src/lib.rs</code> 运行多线程 TCP 中枢,把 agents、reports、存活链路 links 和每 agent 队列 queues 保存在 <code>Arc&lt;Mutex&lt;CoordinatorState&gt;&gt;</code>,同时处理控制端会话与 agent 反向链路(<code>crates/coordinator/src/lib.rs:156</code>、<code>crates/coordinator/src/lib.rs:270</code>、<code>crates/coordinator/src/lib.rs:455</code>、<code>crates/coordinator/src/lib.rs:503</code>)。全部状态易失。<code>AgentIdentity</code>、<code>AgentCommand</code>、<code>AgentResponse</code> 和 <code>WireMessage</code> 定义该协议(<code>crates/coordinator/src/lib.rs:51</code>、<code>crates/coordinator/src/lib.rs:69</code>、<code>crates/coordinator/src/lib.rs:80</code>、<code>crates/coordinator/src/lib.rs:235</code>);<code>crates/coordinator/src/main.rs:4</code> 提供 bind/token 输入并记录在<a href="/faultdeck/zh/configuration.html">配置</a>。操作协议文案在 <a href="/faultdeck/zh/remote-agents.html">Agents</a>。</p><h3 id="_7-证据与可复现模型层" tabindex="-1">7. 证据与可复现模型层 <a class="header-anchor" href="#_7-证据与可复现模型层" aria-label="Permalink to “7. 证据与可复现模型层”">​</a></h3><p><code>crates/report/src/lib.rs</code> 拥有 <code>Scenario</code>、场景哈希、<code>RunReport</code>、HTML 渲染、时间戳和报告比较(<code>crates/report/src/lib.rs:38</code>、<code>crates/report/src/lib.rs:49</code>、<code>crates/report/src/lib.rs:78</code>、<code>crates/report/src/lib.rs:110</code>、<code>crates/report/src/lib.rs:168</code>、<code>crates/report/src/lib.rs:182</code>)。该层无持久状态;CLI 和 coordinator 决定是否保留输出。其 Serde schema 就是报告模型本身,HTML 文案在同一层生成,专题文案在<a href="/faultdeck/zh/reports.html">场景报告</a>。</p><h3 id="拆分理由" tabindex="-1">拆分理由 <a class="header-anchor" href="#拆分理由" aria-label="Permalink to “拆分理由”">​</a></h3><ol><li><code>core::Injection</code> 同时被 CLI 直接构造和 coordinator 校验消费,语义校验不能依赖任一传输宿主(<code>crates/cli/src/main.rs:136</code>、<code>crates/coordinator/src/lib.rs:309</code>)。</li><li>netem 分别暴露 plan、inject、rollback;Agent 需要执行,而适配器和测试需要 dry 规划或记录命令(<code>crates/netem/src/lib.rs:199</code>、<code>crates/netem/src/lib.rs:204</code>、<code>crates/netem/src/lib.rs:232</code>)。</li><li>netem 执行器是 trait,同一命令翻译可指向 Linux <code>tc</code>、dry-run 或测试记录器,而不改策略(<code>crates/netem/src/lib.rs:73</code>、<code>crates/netem/src/lib.rs:163</code>)。</li><li>Disconnect 和包级故障的状态、原子性与回滚机制不同;Agent 将它们路由到独立的 <code>Iptables</code> 与 <code>NetemAdapter</code> 实现(<code>crates/agent/src/lib.rs:196</code>、<code>crates/agent/src/firewall.rs:117</code>、<code>crates/netem/src/lib.rs:204</code>)。</li><li>Agent 的活动故障标记跨连接存在,但命令执行 socket 按连接接受;合并这两个生命周期会让恢复状态变成偶然实现(<code>crates/agent/src/lib.rs:340</code>、<code>crates/agent/src/lib.rs:341</code>)。</li><li>coordinator 状态与分发路由同目标执行分离:中枢把控制端指令转成 agent 反向链路上的 <code>LinkMessage::Dispatch</code>(agent 离线时入队),而真正施加故障由 agent crate 负责(<code>crates/coordinator/src/lib.rs:351</code>、<code>crates/coordinator/src/lib.rs:660</code>)。</li><li>报告需要稳定哈希、回放文本和证据字段,不依赖调用者把它存文件还是 coordinator 内存(<code>crates/report/src/lib.rs:49</code>、<code>crates/report/src/lib.rs:92</code>、<code>crates/cli/src/main.rs:233</code>)。</li></ol>`,35)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};